const VILLAGE = [10.727275, 76.710507];
const CJB = [11.0297, 77.0434];
const COK = [10.152, 76.401];
const PALAKKAD = [10.7867, 76.6548];

class Component extends DCLogic {
  constructor(p) {
    super(p);
    this.step = 0;
    this.maps = {};
  }

  renderVals() {
    return {
      rootRef: (el) => { this.root = el; requestAnimationFrame(() => this.sync()); },
      onStepClick: (e) => {
        const b = e.target.closest('[data-step]');
        if (b) this.setStep(+b.dataset.step);
      },
      onZoom: () => this.openZoom(),
      onCloseZoom: () => this.closeZoom(),
      onPrev: () => this.setStep(Math.max(0, this.step - 1)),
      onNext: () => this.setStep(Math.min(3, this.step + 1)),
      onCopyClick: (e) => {
        const b = e.target.closest('[data-copy]');
        if (!b) return;
        const txt = b.dataset.copy;
        const done = () => {
          const old = b.textContent;
          b.textContent = 'Copied';
          setTimeout(() => { b.textContent = old; }, 1600);
        };
        if (navigator.clipboard) navigator.clipboard.writeText(txt).then(done, done);
        else done();
      }
    };
  }

  componentDidMount() {
    this.sync();
  }

  q(sel) { return this.root ? Array.from(this.root.querySelectorAll(sel)) : []; }

  setStep(n) {
    this.step = n;
    this.sync();
  }

  sync() {
    if (!this.root) return;
    this.q('[data-map-prev], [data-map-next]').forEach(b => {
      const disabled = b.hasAttribute('data-map-prev') ? this.step === 0 : this.step === 3;
      b.disabled = disabled; b.style.opacity = disabled ? '0.4' : '1';
      b.style.cursor = disabled ? 'default' : 'pointer';
    });
    this.q('[data-map-zoom]').forEach(b => { b.hidden = this.step === 2; });

    this.q('[data-step]').forEach((b) => {
      const on = +b.dataset.step === this.step;
      b.style.background = on ? '#5A4420' : '#FFFFFF';
      b.setAttribute('aria-current', on ? 'step' : 'false');
      const num = b.querySelector('[data-num]');
      const title = b.querySelector('[data-title]');
      if (num) num.style.color = on ? '#EEB41E' : '#8F6212';
      if (title) title.style.color = on ? '#F7F4EA' : '#2A2118';
    });
    this.q('[data-panel]').forEach((p) => {
      p.style.display = +p.dataset.panel === this.step ? 'block' : 'none';
    });
    this.q('[data-cap]').forEach((p) => {
      p.style.display = +p.dataset.cap === this.step ? 'block' : 'none';
    });
  }


  openZoom() {
    const img = this.root.querySelector('[data-panel="' + this.step + '"] img');
    const dialog = this.root.querySelector('[data-map-dialog]');
    if (!img || !dialog) return;
    const large = dialog.querySelector('img');
    large.src = img.src; large.alt = img.alt;
    dialog.querySelector('h3').textContent = ['India', 'Kerala', 'Palakkad', 'The grounds'][this.step];
    dialog.showModal();
  }
  closeZoom() { const d = this.root.querySelector('[data-map-dialog]'); if (d) d.close(); }
}
